source.exploreUrl:
@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
push("全部🌊分类",null,1,1)
	arList=["玄幻小说","修真小说","都市小说","历史小说","网游小说","科幻小说","言情小说","其他小说"]
	arList.map((tag,id)=>{
		url=`/lists/${id+1}-{{page}}.html`;
		push(tag, url, 1, 0.25);
		});
//java.log(JSON.stringify(sort))
JSON.stringify(sort)

